		/** 
		 * Tests creating a new Model.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Model");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Model" );

			try {            
				Model entity = ModelService.getModelInstance().createModel( generateNewEntity() );
				thePrimaryKey = entity.getModelId();
				LOGGER.info( "-- Successfully created a Model with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Model. 
		 */
		public Model testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Model" );

			Model entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Model with primary key" );
			msg.append( thePrimaryKey );
			
			ModelFetchOneSummary fetchOneSummary = new ModelFetchOneSummary( thePrimaryKey );

			try {
				entity = ModelService.getModelInstance().getModel( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Model " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Model.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Model." );

			StringBuilder msg = new StringBuilder( "Failed to update a Model : " );        
			Model entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Model." );

				// for use later on...
				thePrimaryKey = entity.getModelId();

				ModelService proxy = ModelService.getModelInstance();            
				proxy.updateModel( entity );   

				LOGGER.info( "-- Successfully saved Model - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Model.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Model." );

			try{
			    Model entity = testRead(); 
				ModelService.getModelInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Model with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Model with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Models.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Models:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Model : " );        
			List<Model> collection  = null;

			try {
				// call the static get method on the ModelService
				collection = ModelService.getModelInstance().getAllModel();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Model entity = null;            
					Iterator<Model> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getModelId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

