		protected Model generateNewEntity() {
			Model entity = new Model( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  null,  new HashSet<>(),  new HashSet<>(),  new HashSet<>(),  new HashSet<>(),  ModelType.values()[0] );
			
			return( entity );
		}

